# Store the given text in an instance variable
@text = 'Contact us at support@example.com for help.'

# Use a regular expression to extract the first email address found
@email_match = @text.match(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/)
# Safely get the matched email string
@email = @email_match ? @email_match[0] : nil

# Return the extracted email
final_answer(answer: @email)
